package com.basics;

public class Unary {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=10;
		System.out.println(a++);
		System.out.println(++a);
		System.out.println(a--);
		System.out.println(--a);
		int b=9;
		System.out.println(b--);
		System.out.println(++b);
		System.out.println(b++);
		System.out.println(--b);
	}

}
